<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'

import { MFA_TEXTS } from '@@/lib/mfa'

export interface MfaCodeSubmit {
  code?: string
  recoveryCode?: string
  rememberDevice: boolean
}

// Second-factor form: 6-digit TOTP code or a recovery code, plus "remember this device" —
// only for the TOTP code (a recovery code never remembers the device; the auth server
// enforces it too). Used by LoginForm and the global step-up dialog. The cancel link is
// rendered when `cancelLabel` is set. Plain HTML — the class names are hooks for your CSS.
const props = defineProps<{
  isPending: boolean
  error: string | null
  submitLabel: string
  cancelLabel?: string
}>()

const emit = defineEmits<{
  submit: [data: MfaCodeSubmit]
  cancel: []
}>()

const useRecovery = ref(false)
const code = ref('')
const recoveryCode = ref('')
const rememberDevice = ref(false)
// Switching code / recovery mode hides the previous attempt's error until the parent
// reports a new one.
const errorHidden = ref(false)
watch(
  () => props.error,
  () => {
    errorHidden.value = false
  },
)
const visibleError = computed(() => (errorHidden.value ? null : props.error))

// Native `autofocus` works only on page load, not for fields mounted later (dialog,
// code step, mode switch) — focus the first field explicitly.
const formRef = ref<HTMLFormElement | null>(null)
function focusField() {
  void nextTick(() => formRef.value?.querySelector<HTMLInputElement>('input')?.focus())
}
onMounted(focusField)

const canSubmit = computed(() =>
  useRecovery.value
    ? recoveryCode.value.replace(/[^a-z0-9]/gi, '').length === 10
    : /^\d{6}$/.test(code.value),
)

function onCodeInput(event: Event) {
  const input = event.target as HTMLInputElement
  code.value = input.value.replace(/\D/g, '').slice(0, 6)
  input.value = code.value
}

function toggleMode() {
  useRecovery.value = !useRecovery.value
  rememberDevice.value = false
  errorHidden.value = true
  focusField()
}

function handleSubmit() {
  if (!canSubmit.value || props.isPending) return
  emit(
    'submit',
    useRecovery.value
      ? { recoveryCode: recoveryCode.value.trim(), rememberDevice: false }
      : { code: code.value, rememberDevice: rememberDevice.value },
  )
}
</script>

<template>
  <form ref="formRef" class="auth-form" novalidate @submit.prevent="handleSubmit">
    <div v-if="useRecovery" class="auth-field">
      <label for="mfa-recovery">Kod zapasowy</label>
      <input
        id="mfa-recovery"
        v-model="recoveryCode"
        autocomplete="off"
        placeholder="xxxxx-xxxxx"
        maxlength="11"
        :disabled="isPending"
        :aria-invalid="visibleError !== null"
      />
      <small>Każdy kod zapasowy działa tylko raz.</small>
    </div>
    <div v-else class="auth-field">
      <label for="mfa-code">Kod z aplikacji uwierzytelniającej</label>
      <input
