    <p v-if="visibleError" role="alert" class="auth-error">{{ visibleError }}</p>

    <p v-if="useRecovery" class="auth-muted">{{ MFA_TEXTS.recoveryCodeHint }}</p>
    <div v-else class="auth-checkbox">
      <input id="mfa-remember" v-model="rememberDevice" type="checkbox" :disabled="isPending" />
      <label for="mfa-remember">Zapamiętaj to urządzenie na 30 dni</label>
    </div>

    <button type="submit" class="auth-submit" :disabled="!canSubmit || isPending">
      {{ isPending ? 'Weryfikacja…' : submitLabel }}
    </button>

    <div class="auth-actions">
      <button type="button" class="auth-link" :disabled="isPending" @click="toggleMode">
        {{ useRecovery ? 'Użyj kodu z aplikacji' : 'Użyj kodu zapasowego' }}
